using System;
using System.Collections.Generic;
using System.Linq;

namespace SoulPilates.Core.DTOs;

/// <summary>
/// One tender line of a (possibly) split payment: a payment method and the
/// amount paid via that method. A checkout can be settled with one OR more of
/// these so a single order tendered across multiple methods (e.g. part cash +
/// part card) credits each income stream its real share in the Payments ledger,
/// keeping the analytics payment-method distribution accurate.
/// </summary>
public class PaymentSplitLine
{
    /// <summary>e.g. "CASH", "CREDIT_CARD", "BANK_TRANSFER", "MOMO", "ZALO_PAY".</summary>
    public string Method { get; set; } = string.Empty;

    /// <summary>Amount tendered via <see cref="Method"/>, in đồng (VND).</summary>
    public decimal Amount { get; set; }
}

/// <summary>
/// Pure validation + normalisation helpers for a set of split payment lines,
/// shared by every payment path (invoice payment and studio class collection)
/// so a split is validated identically everywhere. No I/O — safe to unit-test.
/// </summary>
public static class PaymentSplit
{
    /// <summary>
    /// Whole-đồng tolerance for the sum-to-total check. VND has no minor unit,
    /// so this only absorbs floating→decimal transport noise, never a real
    /// under/over payment.
    /// </summary>
    public const decimal Epsilon = 0.5m;

    /// <summary>
    /// Validate that <paramref name="lines"/> are well-formed and sum to
    /// <paramref name="expectedTotal"/>, returning cleaned lines (method trimmed
    /// + upper-cased, amount rounded to whole đồng). Throws
    /// <see cref="ArgumentException"/> with a human-readable reason on any
    /// problem: empty input, a blank method, a zero/negative amount, or a sum
    /// that does not match the amount due. Callers decide whether to fall back
    /// to a single-method payment BEFORE calling this — null/empty is rejected
    /// here on purpose.
    /// </summary>
    public static List<PaymentSplitLine> Validate(IReadOnlyList<PaymentSplitLine>? lines, decimal expectedTotal)
    {
        if (lines == null || lines.Count == 0)
            throw new ArgumentException("At least one payment line is required.");

        var cleaned = new List<PaymentSplitLine>(lines.Count);
        foreach (var l in lines)
        {
            if (l == null)
                throw new ArgumentException("A payment line is missing.");
            var method = (l.Method ?? string.Empty).Trim().ToUpperInvariant();
            if (method.Length == 0)
                throw new ArgumentException("Each payment line needs a method.");
            if (l.Amount <= 0m)
                throw new ArgumentException("Each payment line amount must be greater than zero.");
            cleaned.Add(new PaymentSplitLine
            {
                Method = method,
                Amount = decimal.Round(l.Amount, 0, MidpointRounding.AwayFromZero),
            });
        }

        var sum = cleaned.Sum(x => x.Amount);
        var target = decimal.Round(expectedTotal, 0, MidpointRounding.AwayFromZero);
        if (Math.Abs(sum - target) > Epsilon)
            throw new ArgumentException(
                $"Payment lines total {sum:N0}đ but the amount due is {target:N0}đ.");

        return cleaned;
    }
}

