if (req is null) return BadRequest(new { error = "Body is required." });
if (req.AmountPaid <= 0m) return BadRequest(new { error = "amountPaid must be greater than zero." });

// Split tender: record one Payment ledger row per {method, amount} line,
// validated to sum to AmountPaid, so a single order paid across multiple
// methods credits each income stream its real share. When no split is
// supplied the payment is recorded once via PaymentMethod as before.
List<PaymentSplitLine> tenders;
if (req.PaymentSplits != null && req.PaymentSplits.Count > 0)
{
    try
    {
        tenders = PaymentSplit.Validate(req.PaymentSplits, req.AmountPaid);
    }
    catch (ArgumentException ex)
    {
        return BadRequest(new { error = ex.Message });
    }
}
else
{
    tenders = new List<PaymentSplitLine>
    {
        new PaymentSplitLine
        {
            Method = string.IsNullOrWhiteSpace(req.PaymentMethod) ? "CASH" : req.PaymentMethod,
            Amount = req.AmountPaid,
        },
    };
}

try
{
    Payment? last = null;
    foreach (var t in tenders)
    {
        last = await _invoiceService.AddPaymentAsync(id, new Payment
        {
            AmountPaid = t.Amount,
            PaymentDate = req.PaymentDate ?? DateTime.UtcNow,
            PaymentMethod = t.Method,
        });
    }
    return Ok(last);
}
