_mposDiscount(base) {
  const dv = parseFloat(document.getElementById('mposDiscAmt').value) || 0;
  const dt = document.getElementById('mposDiscType').value;
  let disc = dt === 'PCT' ? base * dv / 100 : dv;
  if (this._mpos.promo) disc += this._mpos.promo.discount;
  return Math.min(base, Math.max(0, disc));
},

/* ── Split payment (multiple tender methods on one order) ────────────
   The operator can split the order total across ≥1 payment lines, each a
   {method, amount}. Default is a single line = the whole total via one
   method (unchanged UX). Adding a line reveals per-line amounts; the lines
   must sum EXACTLY to the amount actually charged before checkout is
   allowed. On submit each line becomes its own Payment ledger row so every
   income stream is credited its real share. */

/** The real money that will be tendered = product net + class amount. This
 *  mirrors exactly what mposComplete charges (product invoice payment +
 *  class collect), so tenders are validated against what hits the ledger. */
_mposPayTotal() {
  const m = this._mpos; if (!m) return 0;
  const prodSub = m.lines.reduce((s, l) => s + l.unitPrice * l.qty, 0);
  const productNet = Math.max(0, prodSub - this._mposDiscount(prodSub));
  const classAmount = m.chargeDropIn ? m.dropInPrice : 0;
  return Math.round(productNet + classAmount);
},

/** Reset the payment area to single-method mode (called on modal open). */
_mposResetPay() {
  const m = this._mpos; if (m) { m.paySplit = false; m._paySeq = 0; }
  const extra = document.getElementById('mposPayExtra'); if (extra) extra.innerHTML = '';
  const amt0 = document.getElementById('mposPayAmt0'); if (amt0) { amt0.style.display = 'none'; amt0.value = ''; }
  const x0 = document.getElementById('mposPayX0'); if (x0) x0.style.display = 'none';
  const addBtn = document.getElementById('mposPayAddBtn'); if (addBtn) addBtn.textContent = '+ Split payment';
  const info = document.getElementById('mposPaySplit'); if (info) info.style.display = 'none';
},

/** Enter split mode (first click) or append another tender line. */
mposAddPayLine() {
  const m = this._mpos; if (!m) return;
  if (!m.paySplit) {
    // Transition into split mode: line 0 keeps the full total, reveal its
    // amount box + remove control, and relabel the action button.
    m.paySplit = true;
    const amt0 = document.getElementById('mposPayAmt0');
    const x0 = document.getElementById('mposPayX0');
    if (amt0) { amt0.style.display = ''; amt0.value = String(this._mposPayTotal()); }
    if (x0) x0.style.display = '';
    const addBtn = document.getElementById('mposPayAddBtn');
    if (addBtn) addBtn.textContent = '+ Add method';
  }
  // Append a new line prefilled with the current remaining amount so a
  // 2-way split "just works": line 0 = total, new line = 0 remaining.
  const seq = ++m._paySeq;
  const remaining = Math.max(0, this._mposPayTotal() - this._mposGatherTenders(false).reduce((s, t) => s + t.amount, 0));
  const wrap = document.createElement('div');
  wrap.className = 'mpos-pay-line';
  wrap.dataset.seq = String(seq);
  wrap.innerHTML =
    `<select class="form-control mpos-pay-method" onchange="ClassDetailPanel.mposPayRecalc()">
       <option value="CASH">Cash</option>
       <option value="BANK_TRANSFER">Bank Transfer</option>
       <option value="MOMO">MoMo</option>
       <option value="ZALO_PAY">ZaloPay</option>
       <option value="CREDIT_CARD">Credit Card</option>
       <option value="WISE">Wise</option>
       <option value="STRIPE">Stripe</option>
     </select>
     <input type="number" min="0" step="1000" class="form-control mpos-pay-amt" value="${remaining}"
            oninput="ClassDetailPanel.mposPayRecalc()" />
     <button type="button" class="mpos-pay-x" onclick="ClassDetailPanel.mposRemovePayLine(${seq})" aria-label="Remove">×</button>`;
  document.getElementById('mposPayExtra').appendChild(wrap);
  this.mposPayRecalc();
},

/** Remove a tender line. seq 0 = the fixed first line (only clears/collapses
 *  when it's the last extra being removed); a positive seq removes an extra. */
mposRemovePayLine(seq) {
  const extra = document.getElementById('mposPayExtra');
  if (seq !== 0 && extra) {
    const el = extra.querySelector(`.mpos-pay-line[data-seq="${seq}"]`);
    if (el) el.remove();
  }
  // If no extra lines remain, collapse back to single-method mode.
  if (!extra || extra.children.length === 0) this._mposResetPay();
  this.mposPayRecalc();
},

/** Read the current tender lines. When not in split mode returns a single
 *  synthetic line for the whole total. `dropZero` filters out 0/blank lines. */
_mposGatherTenders(dropZero = true) {
  const m = this._mpos;
  if (!m || !m.paySplit) {
    const method = document.getElementById('cdpCpMethod')?.value || 'CASH';
    return [{ method, amount: this._mposPayTotal() }];
  }
  const rows = [];
  const method0 = document.getElementById('cdpCpMethod')?.value || 'CASH';
  const amt0 = Math.round(parseFloat(document.getElementById('mposPayAmt0')?.value) || 0);
  rows.push({ method: method0, amount: amt0 });
  document.querySelectorAll('#mposPayExtra .mpos-pay-line').forEach(el => {
    const method = el.querySelector('.mpos-pay-method')?.value || 'CASH';
    const amount = Math.round(parseFloat(el.querySelector('.mpos-pay-amt')?.value) || 0);
    rows.push({ method, amount });
  });
  return dropZero ? rows.filter(r => r.amount > 0) : rows;
},

/** Validate the split against the amount due, update the remaining/over
 *  indicator, and enable/disable the Complete button accordingly. */
mposPayRecalc() {
  const m = this._mpos; if (!m) return;
  const info = document.getElementById('mposPaySplit');
  const btn = document.getElementById('mposCompleteBtn');
  const payRow = document.getElementById('mposPayRow');
  // Split only applies when money is actually owed and split mode is on.
  const active = m.paySplit && payRow && payRow.style.display !== 'none';
  if (!active) { if (info) info.style.display = 'none'; if (btn) btn.disabled = false; return; }
  const target = this._mposPayTotal();
  const sum = this._mposGatherTenders(false).reduce((s, t) => s + t.amount, 0);
  const diff = Math.round(target - sum); // >0 remaining, <0 over
  if (info) {
    info.style.display = 'flex';
    if (diff === 0) {
      info.className = 'mpos-pay-split ok';
      info.innerHTML = `<span>Split of ${this._mposFmt(target)}</span><span>✓ Balanced</span>`;
    } else {
      info.className = 'mpos-pay-split bad';
      const label = diff > 0 ? `${this._mposFmt(diff)} remaining` : `${this._mposFmt(-diff)} over`;
      info.innerHTML = `<span>Of ${this._mposFmt(target)}</span><span>${label}</span>`;
    }
  }
  if (btn && !/Processing/.test(btn.textContent)) btn.disabled = diff !== 0;
},

/** Waterfall-allocate tender lines across ordered bills (product, class),
 *  splitting a tender across a bill boundary when it straddles. Preserves
 *  each method's total exactly, so no rounding drift between invoices.
 *  Requires sum(tenders) === sum(bills). Returns { [billKey]: [{method,amount}] }. */
_mposAllocate(bills, tenders) {
  const out = {}; bills.forEach(b => { out[b.key] = []; });
  let ti = 0, remain = tenders.length ? tenders[0].amount : 0;
  for (const b of bills) {
    let need = b.amount;
    while (need > 0 && ti < tenders.length) {
      const take = Math.min(need, remain);
