_mposPayTotal() {
  const m = this._mpos; if (!m) return 0;
  const prodSub = m.lines.reduce((s, l) => s + l.unitPrice * l.qty, 0);
  const productNet = Math.max(0, prodSub - this._mposDiscount(prodSub));
  const classAmount = m.chargeDropIn ? m.dropInPrice : 0;
  return Math.round(productNet + classAmount);
},

