_mposPayTotal() {
  const b = this._mposBills();
  return b.reduce((s, x) => s + x.amount, 0);
},

/** The ordered bills money is actually collected against — the product
 *  invoice net, then the class amount — each rounded to whole đồng. Shared
 *  by the split total, the allocation, and mposComplete so they reconcile. */
_mposBills() {
  const m = this._mpos; if (!m) return [];
  const prodSub = m.lines.reduce((s, l) => s + l.unitPrice * l.qty, 0);
  const productNet = Math.round(Math.max(0, prodSub - this._mposDiscount(prodSub)));
  const classAmount = Math.round(m.chargeDropIn ? m.dropInPrice : 0);
  const bills = [];
  if (m.lines.length > 0 && productNet > 0) bills.push({ key: 'product', amount: productNet });
  if (classAmount > 0) bills.push({ key: 'class', amount: classAmount });
  return bills;
},

