/** Remove a tender line. seq 0 = the fixed first line (only clears/collapses
 *  when it's the last extra being removed); a positive seq removes an extra. */
mposRemovePayLine(seq) {
  const extra = document.getElementById('mposPayExtra');
  if (seq !== 0 && extra) {
    const el = extra.querySelector(`.mpos-pay-line[data-seq="${seq}"]`);
    if (el) el.remove();
  }
  // If no extra lines remain, collapse back to single-method mode.
  if (!extra || extra.children.length === 0) this._mposResetPay();
  this.mposPayRecalc();
},

input.new_string:
/** Remove a tender line. seq 0 = the fixed primary line → exit split mode
 *  entirely; a positive seq removes that extra line (and if it was the last
 *  extra, collapse back to single-method mode). */
mposRemovePayLine(seq) {
  if (seq === 0) { this._mposResetPay(); this.mposPayRecalc(); return; }
  const extra = document.getElementById('mposPayExtra');
  if (extra) {
    const el = extra.querySelector(`.mpos-pay-line[data-seq="${seq}"]`);
    if (el) el.remove();
    if (extra.children.length === 0) this._mposResetPay();
  }
  this.mposPayRecalc();
},

