import { readFileSync } from "node:fs";
import { PrismaClient } from "/opt/nxeon/node_modules/@prisma/client/index.js";

for (const line of readFileSync("/opt/nxeon/.env", "utf8").split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m) {
    let v = m[2].trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
    if (!process.env[m[1]]) process.env[m[1]] = v;
  }
}

const CARD_ID = "cmsj1dake0012hljahfoo1p52";
const INPROGRESS_COL = "cmsavfvin000khla4anofdbxt";

const prisma = new PrismaClient();
try {
  const card = await prisma.card.findUnique({ where: { id: CARD_ID }, include: { column: true } });
  if (!card) { console.error("Card not found"); process.exit(1); }
  const col = await prisma.boardColumn.findUnique({ where: { id: INPROGRESS_COL } });
  console.log("Card:", card.title, "| current column:", card.column?.name, "| target:", col?.name, "(board match:", card.boardId === col?.boardId, ")");

  await prisma.card.update({ where: { id: CARD_ID }, data: { columnId: INPROGRESS_COL } });

  const body = [
    "**Split / multiple payment methods — built (branch `feature/pos-split-payments`, tip `ce913fb`).**",
    "",
    "**What was built**",
    "- Checkout modal (`ClassDetailPanel.astro`): a **+ Split payment** control turns the single Payment-method dropdown into per-line `{method, amount}` tender rows. Default stays one method = the whole total (unchanged for the common case).",
    "- Live **remaining / over** indicator; **Complete & check in** is blocked until the lines sum exactly to the amount charged.",
    "- Backend: new `PaymentSplitLine` DTO + `PaymentSplit.Validate` (sum-to-total, positive amounts, non-empty method, whole-đồng rounding). `InvoiceController.AddPayment` and `SchedulingService.CollectStudioPaymentAsync` accept optional `paymentSplits`.",
    "",
    "**How the split is stored & validated**",
    "- Each tender line becomes its own **Payment ledger row** (method + amount) against the order's invoice, so every income stream (Cash / Credit card / Bank transfer / …) is credited its real share.",
    "- Sum-to-total is enforced client-side (button gate) **and** server-side (`PaymentSplit.Validate`, rejects if lines don't add up to the amount due). On submit the tenders are waterfall-allocated across the product-invoice and class bills so per-method totals reconcile with no rounding drift.",
    "- The analytics **payment-method distribution** already aggregates the Payments collection grouped by method, so it now reflects splits automatically — no analytics change needed. Single-method orders behave exactly as before (back-compat). Mongo schemaless — no migration.",
    "",
    "**Verification**: `dotnet build` (API) 0 errors; `astro build` OK. No container builds/restarts, no Mongo writes.",
    "",
    "**Deploy note**: ships on rebuild of the backend + frontend images (Dockerfiles unchanged) — no schema migration, no config changes. Merge `feature/pos-split-payments` when ready.",
  ].join("\n");

  const c = await prisma.cardComment.create({ data: { cardId: CARD_ID, authorName: "Claude", body } });
  const after = await prisma.card.findUnique({ where: { id: CARD_ID }, include: { column: true } });
  console.log("Moved to column:", after.column?.name, "| comment id:", c.id);
} finally {
  await prisma.$disconnect();
}
